/* The encoding of each value: integers little-endian, a bool one byte (wire::codec). */
#ifndef WIRE_CODEC_H
#define WIRE_CODEC_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* wire::codec::DecodeError: a kind, the byte of BadTag and BadBool, the sums of BadCrc. */
typedef enum wire_decode_error_kind {
    WIRE_DECODE_SHORT = 0,
    WIRE_DECODE_BAD_TAG = 1,
    WIRE_DECODE_BAD_BOOL = 2,
    WIRE_DECODE_BAD_CRC = 3
} wire_decode_error_kind;

typedef struct wire_decode_error {
    wire_decode_error_kind kind;
    uint8_t byte;
    uint16_t expected;
    uint16_t found;
} wire_decode_error;

/* What an encode appends to: Rust's Vec<u8>. Zero-initialized is empty; wire_buf_free
 * releases it. Running out of memory aborts, as a Vec's allocation does. */
typedef struct wire_buf {
    uint8_t *data;
    size_t len;
    size_t cap;
} wire_buf;

void wire_buf_push(wire_buf *b, const uint8_t *bytes, size_t n);
void wire_buf_free(wire_buf *b);

/* What a decode reads from: Rust's &mut &[u8]. Each decode takes its bytes off the front. */
typedef struct wire_input {
    const uint8_t *data;
    size_t len;
} wire_input;

/* Encode and Decode of the integers and bool (the impls `integer!` writes, and bool's).
 * A decode returns 0 with *value set, or -1 with *err set: Short leaves the input as it was,
 * BadBool has taken its byte. */
void wire_u8_encode(uint8_t v, wire_buf *out);
void wire_u16_encode(uint16_t v, wire_buf *out);
void wire_u32_encode(uint32_t v, wire_buf *out);
void wire_i32_encode(int32_t v, wire_buf *out);
void wire_bool_encode(bool v, wire_buf *out);
size_t wire_u8_encoded_len(void);
size_t wire_u16_encoded_len(void);
size_t wire_u32_encoded_len(void);
size_t wire_i32_encoded_len(void);
size_t wire_bool_encoded_len(void);
int wire_u8_decode(wire_input *in, uint8_t *value, wire_decode_error *err);
int wire_u16_decode(wire_input *in, uint16_t *value, wire_decode_error *err);
int wire_u32_decode(wire_input *in, uint32_t *value, wire_decode_error *err);
int wire_i32_decode(wire_input *in, int32_t *value, wire_decode_error *err);
int wire_bool_decode(wire_input *in, bool *value, wire_decode_error *err);

/* DecodeError's Display: writes at most cap - 1 bytes and a NUL (cap > 0), returns the
 * length of the whole message. */
size_t wire_decode_error_display(const wire_decode_error *e, char *buf, size_t cap);

#endif

#include "wire/codec.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void wire_buf_push(wire_buf *b, const uint8_t *bytes, size_t n) {
    if (n == 0) {
        return;
    }
    if (b->cap - b->len < n) {
        size_t cap = b->cap ? b->cap : 8;
        while (cap - b->len < n) {
            if (cap > SIZE_MAX / 2) {
                abort();
            }
            cap *= 2;
        }
        uint8_t *data = realloc(b->data, cap);
        if (!data) {
            abort();
        }
        b->data = data;
        b->cap = cap;
    }
    memcpy(b->data + b->len, bytes, n);
    b->len += n;
}

void wire_buf_free(wire_buf *b) {
    free(b->data);
    b->data = NULL;
    b->len = b->cap = 0;
}

/* take: n bytes off the front, or Short. */
static const uint8_t *take(wire_input *in, size_t n, wire_decode_error *err) {
    if (in->len < n) {
        err->kind = WIRE_DECODE_SHORT;
        return NULL;
    }
    const uint8_t *head = in->data;
    in->data += n;
    in->len -= n;
    return head;
}

static void encode_le(uint32_t v, size_t n, wire_buf *out) {
    uint8_t bytes[4];
    for (size_t i = 0; i < n; i++) {
        bytes[i] = (uint8_t)(v >> (8 * i));
    }
    wire_buf_push(out, bytes, n);
}

static int decode_le(wire_input *in, size_t n, uint32_t *v, wire_decode_error *err) {
    const uint8_t *p = take(in, n, err);
    if (!p) {
        return -1;
    }
    uint32_t x = 0;
    for (size_t i = 0; i < n; i++) {
        x |= (uint32_t)p[i] << (8 * i);
    }
    *v = x;
    return 0;
}

void wire_u8_encode(uint8_t v, wire_buf *out) { encode_le(v, 1, out); }
void wire_u16_encode(uint16_t v, wire_buf *out) { encode_le(v, 2, out); }
void wire_u32_encode(uint32_t v, wire_buf *out) { encode_le(v, 4, out); }
void wire_i32_encode(int32_t v, wire_buf *out) { encode_le((uint32_t)v, 4, out); }
void wire_bool_encode(bool v, wire_buf *out) { encode_le(v ? 1u : 0u, 1, out); }

size_t wire_u8_encoded_len(void) { return 1; }
size_t wire_u16_encoded_len(void) { return 2; }
size_t wire_u32_encoded_len(void) { return 4; }
size_t wire_i32_encoded_len(void) { return 4; }
size_t wire_bool_encoded_len(void) { return 1; }

int wire_u8_decode(wire_input *in, uint8_t *value, wire_decode_error *err) {
    uint32_t x;
    if (decode_le(in, 1, &x, err)) {
        return -1;
    }
    *value = (uint8_t)x;
    return 0;
}

int wire_u16_decode(wire_input *in, uint16_t *value, wire_decode_error *err) {
    uint32_t x;
    if (decode_le(in, 2, &x, err)) {
        return -1;
    }
    *value = (uint16_t)x;
    return 0;
}

int wire_u32_decode(wire_input *in, uint32_t *value, wire_decode_error *err) {
    return decode_le(in, 4, value, err);
}

int wire_i32_decode(wire_input *in, int32_t *value, wire_decode_error *err) {
    uint32_t x;
    if (decode_le(in, 4, &x, err)) {
        return -1;
    }
    /* Two's complement, without an implementation-defined conversion. */
    *value = x <= INT32_MAX ? (int32_t)x : -(int32_t)(~x) - 1;
    return 0;
}

int wire_bool_decode(wire_input *in, bool *value, wire_decode_error *err) {
    const uint8_t *p = take(in, 1, err);
    if (!p) {
        return -1;
    }
    if (*p > 1) {
        /* As in the Rust, the byte stays taken. */
        err->kind = WIRE_DECODE_BAD_BOOL;
        err->byte = *p;
        return -1;
    }
    *value = *p == 1;
    return 0;
}

size_t wire_decode_error_display(const wire_decode_error *e, char *buf, size_t cap) {
    int n = 0;
    switch (e->kind) {
    case WIRE_DECODE_SHORT:
        n = snprintf(buf, cap, "input ended inside a value");
        break;
    case WIRE_DECODE_BAD_TAG:
        n = snprintf(buf, cap, "no variant has tag %u", (unsigned)e->byte);
        break;
    case WIRE_DECODE_BAD_BOOL:
        n = snprintf(buf, cap, "%u is not a bool", (unsigned)e->byte);
        break;
    case WIRE_DECODE_BAD_CRC:
        n = snprintf(buf, cap, "checksum %04x, expected %04x", (unsigned)e->found,
                     (unsigned)e->expected);
        break;
    }
    return n < 0 ? 0 : (size_t)n;
}

