//! The encoding of each value: integers little-endian, a `bool` one byte. Implemented in C
//! (c/src/codec.c, declared in c/include/wire/codec.h) behind this unchanged API.

use std::fmt;

/// bindgen's view of c/include/wire/codec.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
pub(crate) mod sys;

/// Writes a value as bytes.
pub trait Encode {
    fn encode(&self, out: &mut Vec<u8>);
    fn encoded_len(&self) -> usize;
}

/// Reads a value back, taking its bytes off the front of `input`.
pub trait Decode: Sized {
    fn decode(input: &mut &[u8]) -> Result<Self, DecodeError>;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecodeError {
    /// The input ended inside a value.
    Short,
    /// An enum's tag no variant has.
    BadTag(u8),
    /// A `bool` that is neither 0 nor 1.
    BadBool(u8),
    /// A frame whose checksum isn't its payload's.
    BadCrc { expected: u16, found: u16 },
}

impl DecodeError {
    fn from_c(e: &sys::wire_decode_error) -> Self {
        match e.kind {
            sys::wire_decode_error_kind_WIRE_DECODE_BAD_TAG => DecodeError::BadTag(e.byte),
            sys::wire_decode_error_kind_WIRE_DECODE_BAD_BOOL => DecodeError::BadBool(e.byte),
            sys::wire_decode_error_kind_WIRE_DECODE_BAD_CRC => {
                DecodeError::BadCrc { expected: e.expected, found: e.found }
            }
            _ => DecodeError::Short,
        }
    }

    fn to_c(self) -> sys::wire_decode_error {
        let mut e = sys::wire_decode_error {
            kind: sys::wire_decode_error_kind_WIRE_DECODE_SHORT,
            byte: 0,
            expected: 0,
            found: 0,
        };
        match self {
            DecodeError::Short => {}
            DecodeError::BadTag(b) => {
                e.kind = sys::wire_decode_error_kind_WIRE_DECODE_BAD_TAG;
                e.byte = b;
            }
            DecodeError::BadBool(b) => {
                e.kind = sys::wire_decode_error_kind_WIRE_DECODE_BAD_BOOL;
                e.byte = b;
            }
            DecodeError::BadCrc { expected, found } => {
                e.kind = sys::wire_decode_error_kind_WIRE_DECODE_BAD_CRC;
                e.expected = expected;
                e.found = found;
            }
        }
        e
    }
}

impl fmt::Display for DecodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let e = self.to_c();
        let mut buf = [0u8; 64];
        // SAFETY: `e` is a valid error and `buf` has room for `buf.len()` bytes.
        let n = unsafe { sys::wire_decode_error_display(&e, buf.as_mut_ptr().cast(), buf.len()) };
        f.write_str(std::str::from_utf8(&buf[..n.min(buf.len() - 1)]).map_err(|_| fmt::Error)?)
    }
}

/// Runs a C encode into a buffer of its own and appends what it wrote to `out`.
fn append(out: &mut Vec<u8>, encode: impl FnOnce(*mut sys::wire_buf)) {
    let mut buf = sys::wire_buf { data: std::ptr::null_mut(), len: 0, cap: 0 };
    encode(&mut buf);
    if buf.len > 0 {
        // SAFETY: the C wrote `buf.len` bytes at `buf.data`.
        out.extend_from_slice(unsafe { std::slice::from_raw_parts(buf.data, buf.len) });
    }
    // SAFETY: `buf` is the C's, freed once.
    unsafe { sys::wire_buf_free(&mut buf) };
}

/// Runs a C decode on `input`, taking what it read off the front.
fn take<T: Default>(
    input: &mut &[u8],
    decode: impl FnOnce(*mut sys::wire_input, *mut T, *mut sys::wire_decode_error) -> i32,
) -> Result<T, DecodeError> {
    let mut c_in = sys::wire_input { data: input.as_ptr(), len: input.len() };
    let mut value = T::default();
    let mut err = DecodeError::Short.to_c();
    let status = decode(&mut c_in, &mut value, &mut err);
    *input = &input[input.len() - c_in.len..];
    if status == 0 {
        Ok(value)
    } else {
        Err(DecodeError::from_c(&err))
    }
}

macro_rules! facade {
    ($($t:ty => $encode:ident, $len:ident, $decode:ident;)*) => {$(
        impl Encode for $t {
            fn encode(&self, out: &mut Vec<u8>) {
                // SAFETY: `b` is the buffer `append` gives.
                append(out, |b| unsafe { sys::$encode(*self, b) });
            }
            fn encoded_len(&self) -> usize {
                // SAFETY: no arguments.
                unsafe { sys::$len() }
            }
        }
        impl Decode for $t {
            fn decode(input: &mut &[u8]) -> Result<Self, DecodeError> {
                // SAFETY: `take` gives an input over `input`, a value and an error.
                take(input, |i, v, e| unsafe { sys::$decode(i, v, e) })
            }
        }
    )*};
}

facade! {
    u8 => wire_u8_encode, wire_u8_encoded_len, wire_u8_decode;
    u16 => wire_u16_encode, wire_u16_encoded_len, wire_u16_decode;
    u32 => wire_u32_encode, wire_u32_encoded_len, wire_u32_decode;
    i32 => wire_i32_encode, wire_i32_encoded_len, wire_i32_decode;
    bool => wire_bool_encode, wire_bool_encoded_len, wire_bool_decode;
}

#[cfg(test)]
mod tests {
