        assert_eq!(u32::decode(&mut &[1u8, 2][..]), Err(DecodeError::Short));
        assert_eq!(bool::decode(&mut &[7u8][..]), Err(DecodeError::BadBool(7)));
        assert_eq!(DecodeError::BadTag(9).to_string(), "no variant has tag 9");
    }
}

/* CRC-16/ARC over a frame's payload (wire::crc). */
#ifndef WIRE_CRC_H
#define WIRE_CRC_H

#include <stddef.h>
#include <stdint.h>

/* The CRC-16/ARC of the len bytes at data (reflected, polynomial 0x8005, initial value 0). */
uint16_t wire_crc16(const uint8_t *data, size_t len);

#endif

