//! CRC-16/ARC over a frame's payload. Implemented in C (c/src/crc.c, declared in
//! c/include/wire/crc.h) behind this unchanged API.

/// bindgen's view of c/include/wire/crc.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// The CRC-16/ARC of `data` (reflected, polynomial 0x8005, initial value 0).
pub fn crc16(data: &[u8]) -> u16 {
    // SAFETY: `data` is valid for `data.len()` bytes.
    unsafe { sys::wire_crc16(data.as_ptr(), data.len()) }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn check_value() {
        assert_eq!(crc16(b"123456789"), 0xBB3D);
        assert_eq!(crc16(b""), 0);
