}

/* The messages, and frames around them: a header, the payload, the payload's CRC
 * (wire::msg). Each message's encode, encoded_len and decode are what its derive(Encode) and
 * derive(Decode) wrote: the fields in order, but #[wire(skip)] ones; an enum's tag byte. */
#ifndef WIRE_MSG_H
#define WIRE_MSG_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "wire/codec.h"

typedef struct wire_header {
    uint8_t kind;
    uint16_t len;
} wire_header;

/* seen is #[wire(skip)]: never written, 0 once decoded. */
typedef struct wire_reading {
    uint16_t sensor;
    int32_t value;
    bool valid;
    uint32_t seen;
} wire_reading;

/* wire::msg::Command, a tagged union; each tag is the variant's byte on the wire. */
typedef enum wire_command_tag {
    WIRE_COMMAND_PING = 0,
    WIRE_COMMAND_SET = 1,
    WIRE_COMMAND_RESET = 2,
    WIRE_COMMAND_REPORT = 3
} wire_command_tag;

typedef struct wire_command {
    wire_command_tag tag;
    union {
        struct {
            uint8_t key;
            uint32_t value;
        } set;
        uint16_t reset;
        struct {
            wire_header header;
            wire_reading reading;
        } report;
    } as;
} wire_command;

void wire_header_encode(const wire_header *h, wire_buf *out);
size_t wire_header_encoded_len(const wire_header *h);
int wire_header_decode(wire_input *in, wire_header *out, wire_decode_error *err);

void wire_reading_encode(const wire_reading *r, wire_buf *out);
size_t wire_reading_encoded_len(const wire_reading *r);
int wire_reading_decode(wire_input *in, wire_reading *out, wire_decode_error *err);

void wire_command_encode(const wire_command *c, wire_buf *out);
size_t wire_command_encoded_len(const wire_command *c);
int wire_command_decode(wire_input *in, wire_command *out, wire_decode_error *err);

/* write_frame: appends the frame of kind around the len bytes at payload to *out. */
void wire_write_frame(uint8_t kind, const uint8_t *payload, size_t len, wire_buf *out);

/* read_frame, #[throws(DecodeError)]: 0 with the frame's header, its payload appended to
 * *payload and the bytes it took in *used; or -1 with *err. */
int wire_read_frame(const uint8_t *bytes, size_t len, wire_header *header, wire_buf *payload,
                    size_t *used, wire_decode_error *err);

/* command_frame: appends the frame of kind 1 around the command to *out. */
void wire_command_frame(const wire_command *c, wire_buf *out);

/* read_command, #[throws(DecodeError)]: 0 with the command in the frame of kind 1 at bytes,
 * or -1 with *err (BadTag with the kind for a frame of another kind). */
int wire_read_command(const uint8_t *bytes, size_t len, wire_command *out,
                      wire_decode_error *err);

#endif

#include "wire/msg.h"

#include <string.h>

#include "wire/crc.h"

/* derive(Encode) and derive(Decode) for Header. */
void wire_header_encode(const wire_header *h, wire_buf *out) {
    wire_u8_encode(h->kind, out);
    wire_u16_encode(h->len, out);
}

size_t wire_header_encoded_len(const wire_header *h) {
    (void)h;
    return wire_u8_encoded_len() + wire_u16_encoded_len();
}

int wire_header_decode(wire_input *in, wire_header *out, wire_decode_error *err) {
    wire_header h;
    if (wire_u8_decode(in, &h.kind, err) || wire_u16_decode(in, &h.len, err)) {
        return -1;
    }
    *out = h;
    return 0;
}

/* derive(Encode) and derive(Decode) for Reading: seen is #[wire(skip)]. */
void wire_reading_encode(const wire_reading *r, wire_buf *out) {
    wire_u16_encode(r->sensor, out);
    wire_i32_encode(r->value, out);
    wire_bool_encode(r->valid, out);
}

size_t wire_reading_encoded_len(const wire_reading *r) {
    (void)r;
    return wire_u16_encoded_len() + wire_i32_encoded_len() + wire_bool_encoded_len();
}

int wire_reading_decode(wire_input *in, wire_reading *out, wire_decode_error *err) {
    wire_reading r;
    if (wire_u16_decode(in, &r.sensor, err) || wire_i32_decode(in, &r.value, err) ||
        wire_bool_decode(in, &r.valid, err)) {
        return -1;
    }
    r.seen = 0; /* Default::default() */
    *out = r;
    return 0;
}

/* derive(Encode) and derive(Decode) for Command: the variant's index as a tag byte, then
 * its fields. */
void wire_command_encode(const wire_command *c, wire_buf *out) {
    wire_u8_encode((uint8_t)c->tag, out);
    switch (c->tag) {
    case WIRE_COMMAND_PING:
        break;
    case WIRE_COMMAND_SET:
        wire_u8_encode(c->as.set.key, out);
        wire_u32_encode(c->as.set.value, out);
        break;
    case WIRE_COMMAND_RESET:
        wire_u16_encode(c->as.reset, out);
        break;
    case WIRE_COMMAND_REPORT:
        wire_header_encode(&c->as.report.header, out);
        wire_reading_encode(&c->as.report.reading, out);
        break;
    }
}

size_t wire_command_encoded_len(const wire_command *c) {
    switch (c->tag) {
    case WIRE_COMMAND_SET:
        return 1 + wire_u8_encoded_len() + wire_u32_encoded_len();
    case WIRE_COMMAND_RESET:
        return 1 + wire_u16_encoded_len();
    case WIRE_COMMAND_REPORT:
        return 1 + wire_header_encoded_len(&c->as.report.header) +
               wire_reading_encoded_len(&c->as.report.reading);
    case WIRE_COMMAND_PING:
    default:
        return 1;
    }
}

int wire_command_decode(wire_input *in, wire_command *out, wire_decode_error *err) {
    uint8_t tag;
    wire_command c;
    memset(&c, 0, sizeof c);
    if (wire_u8_decode(in, &tag, err)) {
        return -1;
    }
    switch (tag) {
    case WIRE_COMMAND_PING:
        break;
    case WIRE_COMMAND_SET:
        if (wire_u8_decode(in, &c.as.set.key, err) || wire_u32_decode(in, &c.as.set.value, err)) {
            return -1;
        }
        break;
    case WIRE_COMMAND_RESET:
        if (wire_u16_decode(in, &c.as.reset, err)) {
            return -1;
        }
        break;
    case WIRE_COMMAND_REPORT:
        if (wire_header_decode(in, &c.as.report.header, err) ||
            wire_reading_decode(in, &c.as.report.reading, err)) {
            return -1;
        }
        break;
    default:
        err->kind = WIRE_DECODE_BAD_TAG;
        err->byte = tag;
        return -1;
    }
    c.tag = (wire_command_tag)tag;
    *out = c;
    return 0;
}

void wire_write_frame(uint8_t kind, const uint8_t *payload, size_t len, wire_buf *out) {
    wire_header header = {kind, (uint16_t)len}; /* `as u16`: truncates, as the Rust does */
    wire_header_encode(&header, out);
    wire_buf_push(out, payload, len);
    wire_u16_encode(wire_crc16(payload, len), out);
}

int wire_read_frame(const uint8_t *bytes, size_t len, wire_header *header, wire_buf *payload,
                    size_t *used, wire_decode_error *err) {
    wire_input input = {bytes, len};
    wire_header h;
    if (wire_header_decode(&input, &h, err)) {
        return -1;
    }
    size_t n = h.len;
    if (input.len < n + 2) {
        err->kind = WIRE_DECODE_SHORT;
        return -1;
    }
    wire_input crc_input = {input.data + n, input.len - n};
    uint16_t found;
    if (wire_u16_decode(&crc_input, &found, err)) {
        return -1;
    }
    uint16_t expected = wire_crc16(input.data, n);
    if (found != expected) {
        err->kind = WIRE_DECODE_BAD_CRC;
        err->expected = expected;
        err->found = found;
        return -1;
    }
    wire_buf_push(payload, input.data, n);
    *header = h;
    *used = len - input.len + n + 2;
    return 0;
}

void wire_command_frame(const wire_command *c, wire_buf *out) {
    wire_buf payload = {0};
    wire_command_encode(c, &payload);
    wire_write_frame(1, payload.data, payload.len, out);
    wire_buf_free(&payload);
}

int wire_read_command(const uint8_t *bytes, size_t len, wire_command *out,
                      wire_decode_error *err) {
    wire_header header;
    wire_buf payload = {0};
    size_t used;
    if (wire_read_frame(bytes, len, &header, &payload, &used, err)) {
        return -1;
    }
    int status = 0;
    if (header.kind != 1) {
        err->kind = WIRE_DECODE_BAD_TAG;
        err->byte = header.kind;
        status = -1;
    } else {
        wire_input input = {payload.data, payload.len};
        status = wire_command_decode(&input, out, err);
    }
    wire_buf_free(&payload);
    return status;
}

