    uint16_t u = 0;
    int32_t i = 0;
    wire_decode_error err;
    wire_u16_encode(0x1234, &out);
    wire_i32_encode(-2, &out);
    CCM_CHECK(out.len == sizeof expected && memcmp(out.data, expected, sizeof expected) == 0);
    wire_input in = {out.data, out.len};
    CCM_CHECK_INT(wire_u16_decode(&in, &u, &err), 0);
    CCM_CHECK_UINT(u, 0x1234);
    CCM_CHECK_INT(wire_i32_decode(&in, &i, &err), 0);
    CCM_CHECK_INT(i, -2);
    CCM_CHECK_UINT(in.len, 0);
    wire_buf_free(&out);
}

static void short_input_and_bad_bool(void)
{
    static const uint8_t two[] = {1, 2};
    static const uint8_t seven[] = {7};
    wire_input in = {two, 2};
    uint32_t u = 0;
    bool b = false;
    wire_decode_error err;
    char text[64];
    CCM_CHECK_INT(wire_u32_decode(&in, &u, &err), -1);
    CCM_CHECK_INT(err.kind, WIRE_DECODE_SHORT);
    in.data = seven;
    in.len = 1;
    CCM_CHECK_INT(wire_bool_decode(&in, &b, &err), -1);
