    let mut used = 0usize;
    let mut err = no_error();
    // SAFETY: `bytes` is valid for its length; the rest are valid out-parameters.
    let status = unsafe {
        sys::wire_read_frame(
            bytes.as_ptr(),
            bytes.len(),
            &mut header,
            &mut payload.0,
            &mut used,
            &mut err,
        )
    };
    if status != 0 {
        return Err(error_from_c(&err));
    }
    Ok((Header::from_c(&header), payload.bytes().to_vec(), used))
}

/// A command in a frame of kind 1.
pub fn command_frame(command: &Command) -> Vec<u8> {
    let mut buf = Buf::new();
    // SAFETY: a valid command and buffer.
    unsafe { sys::wire_command_frame(&command.to_c(), &mut buf.0) };
    buf.bytes().to_vec()
}

/// The command in a frame of kind 1.
pub fn read_command(bytes: &[u8]) -> Result<Command, DecodeError> {
    let mut c = Command::Ping.to_c();
    let mut err = no_error();
    // SAFETY: `bytes` is valid for its length; valid out-parameters.
    let status = unsafe { sys::wire_read_command(bytes.as_ptr(), bytes.len(), &mut c, &mut err) };
    if status != 0 {
        return Err(error_from_c(&err));
    }
    Ok(Command::from_c(&c))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_reading_skips_seen() {
        let r = Reading { sensor: 7, value: -40, valid: true, seen: 99 };
        let mut out = Vec::new();
        r.encode(&mut out);
        assert_eq!(out, [7, 0, 0xd8, 0xff, 0xff, 0xff, 1]);
        assert_eq!(r.encoded_len(), 7);
        let back = Reading::decode(&mut &out[..]).unwrap();
        assert_eq!(back, Reading { seen: 0, ..r });
    }

    #[test]
    fn a_command_round_trips() {
        let c = Command::Set { key: 3, value: 70000 };
        assert_eq!(read_command(&command_frame(&c)), Ok(c));
        assert_eq!(Command::Ping.encoded_len(), 1);
    }

    #[test]
    fn a_bad_tag_and_a_bad_crc() {
        assert_eq!(Command::decode(&mut &[9u8][..]), Err(DecodeError::BadTag(9)));
        let mut frame = write_frame(2, b"abc");
        let last = frame.len() - 1;
        frame[last] ^= 1;
        assert!(matches!(read_frame(&frame), Err(DecodeError::BadCrc { .. })));
    }
}

