//! The messages, and frames around them: a header, the payload, the payload's CRC.
//! Implemented in C (c/src/msg.c, declared in c/include/wire/msg.h) behind this unchanged API:
//! the C holds what `derive(Encode, Decode)` and `#[throws]` wrote, so neither runs here.

use crate::codec::{Decode, DecodeError, Encode};

/// bindgen's view of c/include/wire/msg.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Header {
    pub kind: u8,
    pub len: u16,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reading {
    pub sensor: u16,
    pub value: i32,
    pub valid: bool,
    /// When the reading was last looked at; local, never sent.
    pub seen: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Command {
    Ping,
    Set { key: u8, value: u32 },
    Reset(u16),
    Report(Header, Reading),
}

impl Header {
    fn to_c(self) -> sys::wire_header {
        sys::wire_header { kind: self.kind, len: self.len }
    }
    fn from_c(h: &sys::wire_header) -> Self {
        Header { kind: h.kind, len: h.len }
    }
}

impl Reading {
    fn to_c(&self) -> sys::wire_reading {
        sys::wire_reading {
            sensor: self.sensor,
            value: self.value,
            valid: self.valid,
            seen: self.seen,
        }
    }
    fn from_c(r: &sys::wire_reading) -> Self {
        Reading { sensor: r.sensor, value: r.value, valid: r.valid, seen: r.seen }
    }
}

impl Command {
    fn to_c(&self) -> sys::wire_command {
        // SAFETY: an all-zero wire_command is a valid Ping.
        let mut c: sys::wire_command = unsafe { std::mem::zeroed() };
        match self {
            Command::Ping => c.tag = sys::wire_command_tag_WIRE_COMMAND_PING,
            Command::Set { key, value } => {
                c.tag = sys::wire_command_tag_WIRE_COMMAND_SET;
                c.as_.set.key = *key;
                c.as_.set.value = *value;
            }
            Command::Reset(n) => {
                c.tag = sys::wire_command_tag_WIRE_COMMAND_RESET;
                c.as_.reset = *n;
            }
            Command::Report(h, r) => {
                c.tag = sys::wire_command_tag_WIRE_COMMAND_REPORT;
                c.as_.report.header = h.to_c();
                c.as_.report.reading = r.to_c();
            }
        }
        c
    }
    fn from_c(c: &sys::wire_command) -> Self {
        // SAFETY: the C sets the union's member its tag names.
        unsafe {
            match c.tag {
                sys::wire_command_tag_WIRE_COMMAND_SET => {
                    Command::Set { key: c.as_.set.key, value: c.as_.set.value }
                }
                sys::wire_command_tag_WIRE_COMMAND_RESET => Command::Reset(c.as_.reset),
                sys::wire_command_tag_WIRE_COMMAND_REPORT => Command::Report(
                    Header::from_c(&c.as_.report.header),
                    Reading::from_c(&c.as_.report.reading),
                ),
                _ => Command::Ping,
            }
        }
    }
}

fn error_from_c(e: &sys::wire_decode_error) -> DecodeError {
    match e.kind {
        sys::wire_decode_error_kind_WIRE_DECODE_BAD_TAG => DecodeError::BadTag(e.byte),
        sys::wire_decode_error_kind_WIRE_DECODE_BAD_BOOL => DecodeError::BadBool(e.byte),
        sys::wire_decode_error_kind_WIRE_DECODE_BAD_CRC => {
            DecodeError::BadCrc { expected: e.expected, found: e.found }
        }
        _ => DecodeError::Short,
    }
}

fn no_error() -> sys::wire_decode_error {
    sys::wire_decode_error {
        kind: sys::wire_decode_error_kind_WIRE_DECODE_SHORT,
        byte: 0,
        expected: 0,
        found: 0,
    }
}

/// A C buffer; its bytes go to a `Vec` when it is dropped into one.
struct Buf(sys::wire_buf);

impl Buf {
    fn new() -> Self {
        Buf(sys::wire_buf { data: std::ptr::null_mut(), len: 0, cap: 0 })
    }
    fn bytes(&self) -> &[u8] {
        if self.0.len == 0 {
            return &[];
        }
        // SAFETY: the C wrote `len` bytes at `data`.
        unsafe { std::slice::from_raw_parts(self.0.data, self.0.len) }
    }
}

impl Drop for Buf {
    fn drop(&mut self) {
        // SAFETY: the buffer is the C's, freed once; codec's wire_buf is the same C type.
        unsafe { crate::codec::sys::wire_buf_free((&mut self.0 as *mut sys::wire_buf).cast()) }
    }
}

/// Runs a C decode over `input`, taking what it read off the front.
fn decode_with<C>(
    input: &mut &[u8],
    blank: C,
    decode: impl FnOnce(*mut sys::wire_input, *mut C, *mut sys::wire_decode_error) -> i32,
) -> Result<C, DecodeError> {
    let mut c_in = sys::wire_input { data: input.as_ptr(), len: input.len() };
    let mut value = blank;
    let mut err = no_error();
    let status = decode(&mut c_in, &mut value, &mut err);
    *input = &input[input.len() - c_in.len..];
    if status == 0 {
        Ok(value)
    } else {
        Err(error_from_c(&err))
    }
}

impl Encode for Header {
    fn encode(&self, out: &mut Vec<u8>) {
        let mut buf = Buf::new();
        // SAFETY: a valid header and buffer.
        unsafe { sys::wire_header_encode(&self.to_c(), &mut buf.0) };
        out.extend_from_slice(buf.bytes());
    }
    fn encoded_len(&self) -> usize {
        // SAFETY: a valid header.
        unsafe { sys::wire_header_encoded_len(&self.to_c()) }
    }
}

impl Decode for Header {
    fn decode(input: &mut &[u8]) -> Result<Self, DecodeError> {
        let blank = Header { kind: 0, len: 0 }.to_c();
        // SAFETY: `decode_with` gives an input over `input`, a header and an error.
        decode_with(input, blank, |i, v, e| unsafe { sys::wire_header_decode(i, v, e) })
            .map(|h| Header::from_c(&h))
    }
}

impl Encode for Reading {
    fn encode(&self, out: &mut Vec<u8>) {
        let mut buf = Buf::new();
        // SAFETY: a valid reading and buffer.
        unsafe { sys::wire_reading_encode(&self.to_c(), &mut buf.0) };
        out.extend_from_slice(buf.bytes());
    }
    fn encoded_len(&self) -> usize {
        // SAFETY: a valid reading.
        unsafe { sys::wire_reading_encoded_len(&self.to_c()) }
    }
}

impl Decode for Reading {
    fn decode(input: &mut &[u8]) -> Result<Self, DecodeError> {
        let blank = Reading { sensor: 0, value: 0, valid: false, seen: 0 }.to_c();
        // SAFETY: `decode_with` gives an input over `input`, a reading and an error.
        decode_with(input, blank, |i, v, e| unsafe { sys::wire_reading_decode(i, v, e) })
            .map(|r| Reading::from_c(&r))
    }
}

impl Encode for Command {
    fn encode(&self, out: &mut Vec<u8>) {
        let mut buf = Buf::new();
        // SAFETY: a valid command and buffer.
        unsafe { sys::wire_command_encode(&self.to_c(), &mut buf.0) };
        out.extend_from_slice(buf.bytes());
    }
    fn encoded_len(&self) -> usize {
        // SAFETY: a valid command.
        unsafe { sys::wire_command_encoded_len(&self.to_c()) }
    }
}

impl Decode for Command {
    fn decode(input: &mut &[u8]) -> Result<Self, DecodeError> {
        let blank = Command::Ping.to_c();
        // SAFETY: `decode_with` gives an input over `input`, a command and an error.
        decode_with(input, blank, |i, v, e| unsafe { sys::wire_command_decode(i, v, e) })
            .map(|c| Command::from_c(&c))
    }
}

/// A frame of `kind` around `payload`.
pub fn write_frame(kind: u8, payload: &[u8]) -> Vec<u8> {
    let mut buf = Buf::new();
    // SAFETY: `payload` is valid for its length; a valid buffer.
    unsafe { sys::wire_write_frame(kind, payload.as_ptr(), payload.len(), &mut buf.0) };
    buf.bytes().to_vec()
}

/// The header and payload of the frame at the start of `bytes`, and the bytes after it.
pub fn read_frame(bytes: &[u8]) -> Result<(Header, Vec<u8>, usize), DecodeError> {
    let mut header = Header { kind: 0, len: 0 }.to_c();
    let mut payload = Buf::new();
    let mut used = 0usize;
    let mut err = no_error();
    // SAFETY: `bytes` is valid for its length; the rest are valid out-parameters.
    let status = unsafe {
        sys::wire_read_frame(
            bytes.as_ptr(),
            bytes.len(),
            &mut header,
            &mut payload.0,
            &mut used,
            &mut err,
        )
    };
    if status != 0 {
        return Err(error_from_c(&err));
    }
    Ok((Header::from_c(&header), payload.bytes().to_vec(), used))
}

/// A command in a frame of kind 1.
pub fn command_frame(command: &Command) -> Vec<u8> {
    let mut buf = Buf::new();
    // SAFETY: a valid command and buffer.
    unsafe { sys::wire_command_frame(&command.to_c(), &mut buf.0) };
    buf.bytes().to_vec()
}

/// The command in a frame of kind 1.
pub fn read_command(bytes: &[u8]) -> Result<Command, DecodeError> {
    let mut c = Command::Ping.to_c();
    let mut err = no_error();
    // SAFETY: `bytes` is valid for its length; valid out-parameters.
    let status = unsafe { sys::wire_read_command(bytes.as_ptr(), bytes.len(), &mut c, &mut err) };
    if status != 0 {
        return Err(error_from_c(&err));
    }
    Ok(Command::from_c(&c))
}

