/* The tests of tests/frames.rs, translated from Rust (CodeCoreMorph, D-75). */
#include "codecoremorph_tap.h"

#include <string.h>

#include "wire/codec.h"
#include "wire/msg.h"

/* A message only the tests send, and what its derive(Encode, Decode) wrote: note is
 * #[wire(skip)]. */
typedef struct probe {
    uint32_t id;
    uint8_t note;
    bool echo;
} probe;

static void probe_encode(const probe *p, wire_buf *out)
{
    wire_u32_encode(p->id, out);
    wire_bool_encode(p->echo, out);
}

static int probe_decode(wire_input *in, probe *out, wire_decode_error *err)
{
    probe p;
    if (wire_u32_decode(in, &p.id, err) || wire_bool_decode(in, &p.echo, err)) {
        return -1;
    }
    p.note = 0;
    *out = p;
    return 0;
}

static void frames_follow_each_other(void)
{
    wire_buf bytes = {0};
    wire_command reset = {WIRE_COMMAND_RESET, {.reset = 513}};
    wire_header header;
    wire_buf payload = {0};
    size_t used = 0;
    wire_decode_error err;
    wire_command back = {WIRE_COMMAND_PING, {.reset = 0}};
    wire_write_frame(2, (const uint8_t *)"hello", 5, &bytes);
    wire_command_frame(&reset, &bytes);
    CCM_CHECK_INT(wire_read_frame(bytes.data, bytes.len, &header, &payload, &used, &err), 0);
    CCM_CHECK_UINT(header.kind, 2);
    CCM_CHECK_UINT(header.len, 5);
    CCM_CHECK(payload.len == 5 && memcmp(payload.data, "hello", 5) == 0);
    CCM_CHECK_INT(wire_read_command(bytes.data + used, bytes.len - used, &back, &err), 0);
    CCM_CHECK_INT(back.tag, WIRE_COMMAND_RESET);
    CCM_CHECK_UINT(back.as.reset, 513);
    wire_buf_free(&payload);
    wire_buf_free(&bytes);
}

static void a_report_nests_its_parts(void)
{
    wire_command c;
    wire_command back = {WIRE_COMMAND_PING, {.reset = 0}};
    wire_decode_error err;
    wire_buf frame = {0};
    memset(&c, 0, sizeof c);
    c.tag = WIRE_COMMAND_REPORT;
    c.as.report.header.kind = 9;
    c.as.report.reading.sensor = 1;
    c.as.report.reading.value = 2;
    c.as.report.reading.valid = false;
    c.as.report.reading.seen = 3;
    wire_command_frame(&c, &frame);
    CCM_CHECK_UINT(frame.len, 3 + 1 + 3 + 7 + 2);
    CCM_CHECK_INT(wire_read_command(frame.data, frame.len, &back, &err), 0);
    CCM_CHECK_INT(back.tag, WIRE_COMMAND_REPORT);
    CCM_CHECK_UINT(back.as.report.header.kind, 9);
    CCM_CHECK_UINT(back.as.report.header.len, 0);
    CCM_CHECK_UINT(back.as.report.reading.sensor, 1);
    CCM_CHECK_INT(back.as.report.reading.value, 2);
    CCM_CHECK(!back.as.report.reading.valid);
    CCM_CHECK_UINT(back.as.report.reading.seen, 0);
    wire_buf_free(&frame);
}

static void a_test_message_round_trips(void)
{
    probe p = {0xdeadbeefu, 5, true};
    probe back = {0, 0, false};
    wire_decode_error err;
    wire_buf out = {0};
    static const uint8_t expected[] = {0xef, 0xbe, 0xad, 0xde, 1};
    probe_encode(&p, &out);
    CCM_CHECK(out.len == sizeof expected && memcmp(out.data, expected, sizeof expected) == 0);
    wire_input in = {out.data, out.len};
    CCM_CHECK_INT(probe_decode(&in, &back, &err), 0);
    CCM_CHECK_UINT(back.id, 0xdeadbeefu);
    CCM_CHECK_UINT(back.note, 0);
    CCM_CHECK(back.echo);
    wire_buf_free(&out);
}

static void a_short_frame(void)
{
    static const uint8_t bytes[] = {1, 4, 0, 1};
    wire_header header;
    wire_buf payload = {0};
    wire_buf frame = {0};
    size_t used = 0;
    wire_decode_error err;
    wire_command c;
    CCM_CHECK_INT(wire_read_frame(bytes, sizeof bytes, &header, &payload, &used, &err), -1);
    CCM_CHECK_INT(err.kind, WIRE_DECODE_SHORT);
    wire_write_frame(3, NULL, 0, &frame);
    CCM_CHECK_INT(wire_read_command(frame.data, frame.len, &c, &err), -1);
    CCM_CHECK_INT(err.kind, WIRE_DECODE_BAD_TAG);
    CCM_CHECK_UINT(err.byte, 3);
    wire_buf_free(&payload);
    wire_buf_free(&frame);
}

int main(int argc, char **argv)
{
    CCM_SELECT(argc, argv);
    CCM_RUN(frames_follow_each_other);
    CCM_RUN(a_report_nests_its_parts);
    CCM_RUN(a_test_message_round_trips);
    CCM_RUN(a_short_frame);
    return ccm_done();
}
